<script setup>
import {ref,watch} from 'vue'
import {Eye,EyeOff,X} from 'lucide-vue-next'
import {authSession,signIn,cancelLogin} from '../authState.js'
import {useDialogFocus} from '../useDialogFocus.js'
import {artwork} from '../assets.js'
const dialog=ref(null),username=ref(''),password=ref(''),remember=ref(false),visible=ref(false)
useDialogFocus(dialog)
watch(()=>authSession.open,open=>{if(!open){password.value='';visible.value=false}})
</script>
<template><dialog v-if="authSession.open" ref="dialog" class="auth-dialog" aria-labelledby="auth-title" @cancel.prevent="cancelLogin"><button class="auth-close" aria-label="关闭登录" :disabled="authSession.busy" @click="cancelLogin"><X :size="21"/></button><aside class="auth-art" aria-hidden="true"><img class="auth-scene" src="/assets/access-v1/login-scene.webp" alt=""><div class="auth-brand"><img :src="artwork.logo" alt=""><strong>知行伴学</strong></div><p>让好奇，慢慢成为能力</p></aside><section class="auth-form"><h2 id="auth-title">登录后，继续与林知学习</h2><p class="auth-intro">浏览课程与资料无需登录；<br>使用 AI 讲解、路线生成和项目审阅时再登录。</p><form @submit.prevent="signIn(username,password,remember)"><label for="auth-user">账号</label><input id="auth-user" v-model="username" autocomplete="username" required maxlength="80" placeholder="请输入学习账号" autofocus :disabled="authSession.busy"><label for="auth-pass">密码</label><div class="auth-password"><input id="auth-pass" v-model="password" :type="visible?'text':'password'" autocomplete="current-password" required maxlength="200" placeholder="请输入密码" :disabled="authSession.busy"><button type="button" :aria-label="visible?'隐藏密码':'显示密码'" :aria-pressed="visible" @click="visible=!visible"><EyeOff v-if="visible" :size="20"/><Eye v-else :size="20"/></button></div><div class="auth-options"><label><input v-model="remember" type="checkbox" :disabled="authSession.busy">保持登录</label><span>使用分配的学习账号</span></div><p v-if="authSession.error" class="auth-error" role="alert">{{ authSession.error }}</p><button class="primary-button auth-submit" :disabled="authSession.busy||!username.trim()||!password">{{authSession.busy?'正在登录…':'登录并继续'}}</button><button type="button" class="auth-browse" :disabled="authSession.busy" @click="cancelLogin">继续浏览</button><small>登录成功后，将返回刚才的操作。</small></form></section></dialog></template>
<style>
.auth-dialog{padding:0;border:1px solid #d9e7e1;border-radius:22px;width:min(850px,calc(100vw - 32px));max-width:850px;max-height:calc(100dvh - 32px);overflow:auto;color:#153f42;background:#fff;box-shadow:0 22px 80px #073c3f36}.auth-dialog[open]{display:grid;grid-template-columns:32% 1fr}.auth-dialog::backdrop{background:#153f4266;backdrop-filter:blur(2px)}.auth-close{position:absolute;right:18px;top:18px;z-index:2;display:grid;place-items:center;border:0;background:transparent;color:#1b5654;padding:6px;border-radius:8px}.auth-art{position:relative;overflow:hidden;min-height:550px;background:#e7f1e9}.auth-scene{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.auth-brand{position:relative;display:flex;align-items:center;gap:10px;padding:42px 20px;font-size:25px;white-space:nowrap}.auth-brand img{width:45px;height:45px;object-fit:contain}.auth-art>p{position:absolute;bottom:48px;width:100%;text-align:center;font-family:var(--font-serif,serif);font-size:17px;color:#164e4b}.auth-form{padding:64px 34px 26px}.auth-form h2{font-size:27px;line-height:1.5;letter-spacing:.01em;margin:0 0 8px;font-family:var(--font-serif,serif);color:#093e41}.auth-intro{font-size:14px;line-height:1.8;color:#657b78;margin:0 0 28px}.auth-form form{display:grid;grid-template-columns:44px minmax(0,1fr);align-items:center;gap:18px 12px}.auth-form form>label{font-weight:600;font-size:14px}.auth-form input:not([type=checkbox]){width:100%;height:46px;border:1px solid #d7e3e1;border-radius:10px;background:white;padding:0 13px;color:#164b49;font-size:15px;outline:none!important;box-sizing:border-box}.auth-form input:not([type=checkbox]):focus-visible{border-color:#2e8d83;box-shadow:0 0 0 3px #50a5991f}.auth-password{position:relative}.auth-password input{padding-right:42px!important}.auth-password button{position:absolute;right:8px;top:8px;border:0;background:none;color:#54716e;display:grid;place-items:center;width:30px;height:30px}.auth-options,.auth-submit,.auth-browse,.auth-error,.auth-form small{grid-column:1/-1}.auth-options{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px;color:#7a8c88}.auth-options label{display:flex;align-items:center;gap:7px;color:#405e59}.auth-options input{accent-color:#22655d;width:17px;height:17px}.auth-submit{width:100%;min-height:48px;justify-content:center;margin-top:7px}.auth-browse{border:0;background:none;color:#5a7771;font-size:14px;padding:0}.auth-form small{text-align:center;color:#8b9c99;font-size:12px}.auth-error{margin:0;color:#a03e34;font-size:13px;line-height:1.6}@media(max-width:650px){.auth-dialog[open]{grid-template-columns:1fr}.auth-art{display:none}.auth-form{padding:58px 24px 28px}.auth-form h2{font-size:23px}.auth-form form{grid-template-columns:38px minmax(0,1fr)}}
</style>
